import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"首次运行验证","description":"用你自己的模型跑一次真实的“改文件 → 跑测试”最小任务，确认首跑链路可用。","frontmatter":{"title":"首次运行验证","description":"用你自己的模型跑一次真实的“改文件 → 跑测试”最小任务，确认首跑链路可用。","outline":[2,3]},"headers":[],"relativePath":"reference/first-run.md","filePath":"reference/first-run.md","lastUpdated":1795340054000}'),i={name:"reference/first-run.md"};function d(o,e,r,l,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="首次运行验证" tabindex="-1">首次运行验证 <a class="header-anchor" href="#首次运行验证" aria-label="Permalink to &quot;首次运行验证&quot;">​</a></h1><p class="lead">单元测试通过不等于你的模型、-key、工具循环和测试链路真的通。这一页提供一个可复现的最小真实任务：让模型读一个文件、写出预期答案、跑一次测试，并返回结果。它复用服务端已有的首次任务验证逻辑，不另起一套模型调用。</p><h2 id="它验证什么" tabindex="-1">它验证什么 <a class="header-anchor" href="#它验证什么" aria-label="Permalink to &quot;它验证什么&quot;">​</a></h2><p>一次成功的首跑会同时证明四件事：</p><ol><li><strong>模型可用</strong>：你配置的 provider 与 key 能正常返回，并驱动多轮工具调用。</li><li><strong>工具循环可用</strong>：模型能 <code>read_file</code> 读取 <code>hello.txt</code>、<code>write_file</code> 写出 <code>answer.txt</code>。</li><li><strong>测试链路可用</strong>：<code>npm test</code> 真的执行了 <code>check.mjs</code>，并以退出码 0 结束。</li><li><strong>产物与收尾可用</strong>：任务以 <code>completed</code> 结束，<code>answer.txt</code> 内容为 <code>hearth</code>。</li></ol><p>四项都通过才算首跑成功；任何一项失败都会给出具体检查项，便于定位是 key、模型、工具还是环境问题。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ol><li>在 <strong>设置 → 模型</strong> 创建模型档案（选择服务商或自定义，填入 API Key），并在 <strong>设置 → 执行器</strong> 把它绑定到执行器。</li><li>启动本地服务端：开发模式 <code>npm run dev</code>，或生产式 <code>npm run build &amp;&amp; npm start</code>。</li><li>确认 <a href="http://127.0.0.1:4317/api/ready" target="_blank" rel="noreferrer">http://127.0.0.1:4317/api/ready</a> 返回 <code>{&quot;ok&quot;:true,...}</code>。</li></ol><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 真实模式：用你配置的聊天模型跑一次真实任务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> first:run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定服务地址</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/first-run.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317</span></span></code></pre></div><p>输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首次运行验证（真实模型）</span></span>
<span class="line"><span>结果：passed</span></span>
<span class="line"><span>  [PASS] 模型调用了工具并完成 (completed)</span></span>
<span class="line"><span>  [PASS] answer.txt 内容正确 (hearth)</span></span>
<span class="line"><span>  [PASS] 真实测试通过 (任务以 completed 结束)</span></span>
<span class="line"><span>说明：模型已经完成一次真实的读写和测试。</span></span>
<span class="line"><span>完成：模型已经跑通一次真实的读写与测试。</span></span></code></pre></div><p>退出码：<code>0</code> 通过；<code>1</code> 任务失败；<code>2</code> 环境或配置问题（服务未启动、模型未配置等）。</p><h2 id="离线自检-fake" tabindex="-1">离线自检（--fake） <a class="header-anchor" href="#离线自检-fake" aria-label="Permalink to &quot;离线自检（--fake）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> first:run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fake</span></span></code></pre></div><p><code>--fake</code> 不联网、不需要模型、不需要服务，在临时目录里确定性地复现同一套「写 <code>answer.txt</code> → <code>node check.mjs</code>」流程，用来验证<strong>脚本自身</strong>的输出与退出码。它<strong>不能</strong>证明你的模型可用——真实模型请用默认模式。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>无法连接本地服务</code></td><td>服务端未启动或端口不对</td><td>先 <code>npm start</code>；端口不同用 <code>--base-url</code></td></tr><tr><td><code>尚未配置聊天模型</code></td><td>未绑定可用的聊天模型档案</td><td>在 设置 → 模型 / 执行器 完成绑定后重试</td></tr><tr><td><code>Access to model denied</code> 等</td><td>key 无权限或额度不足</td><td>换用有权限的 key 或服务</td></tr><tr><td>任务超时</td><td>模型响应慢或工具循环卡住</td><td>检查网络与模型状态；必要时换执行器</td></tr><tr><td><code>answer.txt 内容正确</code> 失败</td><td>模型未按指令写文件</td><td>看任务说明与执行记录，确认工具是否被正确授权</td></tr></tbody></table><h2 id="与自动测试的关系" tabindex="-1">与自动测试的关系 <a class="header-anchor" href="#与自动测试的关系" aria-label="Permalink to &quot;与自动测试的关系&quot;">​</a></h2><p><code>--fake</code> 的自检逻辑与服务端 <code>onboarding-verify</code> 使用同一套 fixture，但<strong>自动测试</strong>（<code>npm test</code> 中的 <code>onboarding-verify.test.ts</code>）通过注入 fake runner 覆盖成功与失败路径，是确定性的回归门禁。本脚本的真实模式则是对<strong>当前代码 + 你自己的模型</strong>做一次端到端确认，两者互补：前者保证代码正确，后者保证你的环境真的能用。</p>`,20)])])}const g=a(i,[["render",d]]);export{k as __pageData,g as default};
